/**
 * Raycast AI Extension tool: @secretary.ask
 *
 * Bridges Raycast AI to the user's personal secretary agent running on `air`.
 *
 * Transport: SSE stream from /chat/stream. The server emits 'status' events
 * while the agent is working (keeps the connection alive past the 90s mark
 * that previously killed enrichment-heavy requests like "save this link"),
 * then a single 'result' event with the final reply.
 *
 * Failure-handling rules:
 * - Always return a string. Never return empty, undefined, or throw out of the
 *   default export — Raycast AI's LLM interprets all of those as "tool produced
 *   nothing" and either retries (wastefully) or hallucinates a fallback.
 * - On success, return the reply directly — no decoration.
 * - On failure, return text that BEGINS with "[secretary-tool-error]" so the
 *   orchestrator LLM clearly knows this is an error, not a substantive reply.
 *   Include the underlying cause (HTTP code, timeout, exception text) so the
 *   LLM can either retry intelligently or tell the user.
 * - Wall-clock budget of 180s per endpoint — matches the server-side claude
 *   timeout (300s) less headroom, and stays under Raycast AI's own tool-call
 *   timeout (~2 min) so we can surface a controlled error if work overruns.
 */

type Input = {
  /** The natural-language question or instruction to send to the secretary. May be long. */
  question: string;
};

const ENDPOINTS = [
  "http://air.tail97979c.ts.net:8080/chat/stream",
  "http://100.103.103.57:8080/chat/stream",
];
const FETCH_TIMEOUT_MS = 180_000;

type ResultEvent = {
  reply?: string;
  thread?: string;
  duration_s?: number;
  exit_code?: number;
  error?: string;
};

type StreamOutcome =
  | { kind: "result"; result: ResultEvent }
  | { kind: "error"; message: string };

async function readSseStream(
  resp: Response,
  ctrl: AbortController,
): Promise<StreamOutcome> {
  if (!resp.body) {
    return { kind: "error", message: "no response body" };
  }
  const reader = resp.body.getReader();
  const decoder = new TextDecoder();
  let buf = "";
  try {
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      buf += decoder.decode(value, { stream: true });
      const parts = buf.split("\n\n");
      buf = parts.pop() || "";
      for (const part of parts) {
        if (!part.trim()) continue;
        let evType = "message";
        let dataLine = "";
        for (const line of part.split("\n")) {
          if (line.startsWith("event: ")) evType = line.slice(7).trim();
          else if (line.startsWith("data: ")) dataLine = line.slice(6);
        }
        if (!dataLine) continue;
        let data: unknown;
        try {
          data = JSON.parse(dataLine);
        } catch {
          continue;
        }
        if (evType === "result") {
          ctrl.abort(); // cleanly close the stream after the terminal event
          return { kind: "result", result: data as ResultEvent };
        }
        // 'status' events are intentionally discarded — they're connection
        // keep-alives, not content. The AI tool surface has no progress UI.
      }
    }
  } catch (e) {
    return { kind: "error", message: (e as Error).message || String(e) };
  }
  return { kind: "error", message: "stream ended without result event" };
}

export default async function (input: Input): Promise<string> {
  const text = (input.question || "").trim();
  if (!text) {
    return "[secretary-tool-error] No question was passed to the tool. Call with a non-empty 'question' parameter.";
  }

  const body = JSON.stringify({ text });
  const attempts: string[] = [];

  for (const endpoint of ENDPOINTS) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), FETCH_TIMEOUT_MS);
    try {
      const resp = await fetch(endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "text/event-stream",
        },
        body,
        signal: ctrl.signal,
      });

      if (!resp.ok) {
        attempts.push(`${endpoint}: HTTP ${resp.status} ${resp.statusText}`);
        continue;
      }

      const outcome = await readSseStream(resp, ctrl);
      if (outcome.kind === "error") {
        const isAbort =
          ctrl.signal.aborted &&
          outcome.message.toLowerCase().includes("abort");
        attempts.push(
          `${endpoint}: ${isAbort ? `timeout after ${FETCH_TIMEOUT_MS / 1000}s` : outcome.message}`,
        );
        continue;
      }

      const data = outcome.result;
      if (data.error) {
        attempts.push(`${endpoint}: server error: ${data.error}`);
        continue;
      }

      const reply = (data.reply || "").trim();
      if (!reply) {
        return (
          "[secretary-tool-error] Secretary processed the request but returned no text. " +
          `(duration ${data.duration_s ?? "?"}s, exit_code ${data.exit_code ?? "?"}). ` +
          "This is rare — likely a transient agent issue. Tell the user the secretary returned " +
          "an empty reply and suggest they try rephrasing or wait a moment and retry."
        );
      }

      return reply;
    } catch (e) {
      const err = e as Error;
      const isAbort = err.name === "AbortError";
      attempts.push(
        `${endpoint}: ${isAbort ? `timeout after ${FETCH_TIMEOUT_MS / 1000}s` : err.message}`,
      );
      continue;
    } finally {
      clearTimeout(timer);
    }
  }

  return (
    "[secretary-tool-error] Could not reach the secretary on `air`. Attempts:\n" +
    attempts.map((a) => `  - ${a}`).join("\n") +
    "\n\nLikely causes (in order of likelihood): " +
    `(1) the request took longer than ${FETCH_TIMEOUT_MS / 1000}s and timed out — the underlying agent may still be running; ` +
    "(2) Tailscale isn't routing on the laptop right now (test: ping air.tail97979c.ts.net); " +
    "(3) vault-view daemon isn't running on `air` (test: ssh air 'launchctl list | grep vault-view'). " +
    "Tell the user what's likely wrong; do NOT fabricate a substantive answer about their personal data."
  );
}
